import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`job-cost-audit`,heroTitle:`Audit your job costs in minutes`,heroSubtitle:`Perplexity Computer maps actuals against estimates, flags margin overruns, and delivers a profit leak report — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Mapping line items against original estimates`,`Calculating gross margin by cost category`,`Identifying margin fade patterns across similar jobs`,`Profit leak report with recommended process changes — ready to review`],generatingSteps:[`Analyzing your job cost data for labor, materials, subs, and equipment`,`Designing an agent to compare actuals against estimates and approved change orders`,`Configuring margin analysis by cost category and overrun detection across jobs`,`Setting up your profit leak report with actionable recommendations for future bids`],featureSectionTitle:`From cost export to profit leak report`,featureCardTitles:[`Connects to your construction stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`QuickBooks, Google Sheets, Google Drive, Airtable, Dropbox Sign — Computer pulls from your accounting and project tools so every line item gets audited in one workflow.`,`Estimate-vs-actual variance tables. Gross margin breakdowns by cost category. Margin fade trend analysis. A profit leak report with specific process changes to protect future bids.`],capabilitySectionTitle:`Your cost auditor, on autopilot`,capabilitySectionSubtitle:`Upload your job costs, step away, come back to a complete margin analysis.`,capabilityCards:[{title:`Variance Analysis`,description:`Computer can map every line item — labor hours, material costs, sub invoices, equipment charges — against the original estimate and approved change orders.`},{title:`Margin Breakdown`,description:`Computer can calculate gross margin by cost category and flag exactly where overruns eroded your profit on each job.`},{title:`Margin Fade Detection`,description:`Computer can compare patterns across similar jobs — spotting recurring cost leaks that compound across your project portfolio.`},{title:`Connect Your Tools`,description:`Computer can pull from QuickBooks, Google Sheets, Google Drive, and Airtable — build workflows across your entire accounting and project management stack.`},{title:`Remember & Learn`,description:`Computer can remember your cost codes, job types, and historical margins across sessions — so every audit gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can re-run audits on new job cost exports and flag when margin erosion exceeds your thresholds before a project closes out.`}]});export{t as default};
